// Extract sender email and message body from Gmail message
const msg = $input.item.json;

// Extract sender email from headers
const headers = msg.payload?.headers || [];
const fromHeader = headers.find(h => h.name.toLowerCase() === 'from');
const fromRaw = fromHeader?.value || '';

// Parse email from "Name <email@domain.com>" format
const emailMatch = fromRaw.match(/<([^>]+)>/) || fromRaw.match(/([\w.+%-]+@[\w.-]+\.[a-z]{2,})/i);
const senderEmail = emailMatch ? emailMatch[1].toLowerCase() : '';

// Extract name
const nameMatch = fromRaw.match(/^([^<]+)</);
const senderName = nameMatch ? nameMatch[1].trim().replace(/"/g, '') : senderEmail.split('@')[0];

// Extract message body (try plain text first)
let body = '';
const parts = msg.payload?.parts || [];
const textPart = parts.find(p => p.mimeType === 'text/plain');
if (textPart?.body?.data) {
  body = Buffer.from(textPart.body.data, 'base64').toString('utf-8');
} else if (msg.snippet) {
  body = msg.snippet;
}

// Truncate body to first 500 chars for classification
const bodyTruncated = body.substring(0, 500);

return [{
  json: {
    message_id: msg.id,
    thread_id: msg.threadId,
    sender_email: senderEmail,
    sender_name: senderName,
    message_body: bodyTruncated,
    received_date: new Date().toISOString().split('T')[0]
  }
}];

