// Parse sentiment response and prepare update
const claudeResp = $input.item.json;
const text = claudeResp?.content?.[0]?.text || '{}';

let parsed;
try {
  const match = text.match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : { sentiment: 'lukewarm', key_signal: 'could not parse' };
} catch(e) {
  parsed = { sentiment: 'lukewarm', key_signal: 'parse error' };
}

// Get lead record
const leadRecords = $('Find Lead in Airtable').item.json.records || [];
const lead = leadRecords[0];
const leadFields = lead?.fields || {};

// Determine new stage
const sentimentToStage = {
  warm: 'Hot Lead',
  lukewarm: 'Lukewarm',
  'not-fit': 'Dead',
  unsubscribe: 'Dead'
};

const senderInfo = $('Extract Sender & Body').item.json;

return [{
  json: {
    record_id: lead?.id || '',
    ig_handle: leadFields.ig_handle || '',
    email: senderInfo.sender_email,
    name: senderInfo.sender_name || leadFields.first_name || senderInfo.sender_email,
    message_body: senderInfo.message_body,
    message_id: senderInfo.message_id,
    sentiment: parsed.sentiment,
    key_signal: parsed.key_signal,
    new_stage: sentimentToStage[parsed.sentiment] || 'Lukewarm',
    stop_sequence: ['not-fit', 'unsubscribe'].includes(parsed.sentiment),
    reply_date: new Date().toISOString().split('T')[0]
  }
}];

